  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [schoolToDelete, setSchoolToDelete] = useState<SchoolListItem | null>(null);
  const { pushToast } = useToast();

  const handleCopyInviteCode = async (code: string, id: number) => {
    await navigator.clipboard.writeText(code);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleDeleteClick = (school: SchoolListItem) => {
    setSchoolToDelete(school);
    setConfirmOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!schoolToDelete) return;
    setDeletingId(schoolToDelete.id);
    try {
      await deleteSchool(schoolToDelete.id);
      setSchools((prev) => prev.filter((s) => s.id !== schoolToDelete.id));
      pushToast({
        title: "School deleted",
        description: `"${schoolToDelete.name}" has been deleted.`,
        tone: "success",
      });
    } catch (error) {
      pushToast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to delete school",
        tone: "error",
      });
    } finally {
      setDeletingId(null);
      setConfirmOpen(false);
      setSchoolToDelete(null);
    }
  };

  const handleCancelDelete = () => {
    setConfirmOpen(false);
    setSchoolToDelete(null);
  };

  return (
    <div className="space-y-6">
      <AdminPageHeader
        eyebrow="Admin Schools"
        title="School Management"
        subtitle="Create and manage partner schools. Each school gets an invite code for students."
      />

      <ContentListTable
        title="Schools"
        items={schools}
        addHref="/admin/schools/add"
        addLabel="Add School"
        emptyMessage="No schools found. Create one to get started."
        getItemId={(s) => s.id}
        onDelete={(s) => handleDeleteClick(s)}
        columns={[
          {
            key: "name",
            header: "School",
            render: (s) => (
              <div className="flex items-center gap-3">
                <div className="flex h-8 w-8 items-center justify-center rounded-full bg-[var(--bg-subtle)]">
                  <GraduationCap className="h-4 w-4 text-[var(--text-secondary)]" />
                </div>
                <div>
                  <p className="text-sm font-medium text-[var(--text-primary)]">{s.name}</p>
                  <p className="text-xs text-[var(--text-secondary)]">{s.board}</p>
                </div>
              </div>
            ),
          },
          {
            key: "students",
            header: "Students",
            render: (s) => (
              <span className="text-sm text-[var(--text-primary)]">{s.studentCount}</span>
            ),
            className: "w-24",
          },
          {
            key: "invite",
            header: "Invite Code",
            render: (s) => (
              <div className="flex items-center gap-2">
                <code className="rounded bg-[var(--bg-subtle)] px-2 py-1 text-xs font-mono text-[var(--text-primary)]">
                  {s.inviteCode}
                </code>
                <button
                  onClick={() => handleCopyInviteCode(s.inviteCode, s.id)}
                  className="rounded-md p-1 text-[var(--text-secondary)] hover:bg-[var(--bg-subtle)] hover:text-[var(--text-primary)] transition-colors"
                >
                  {copiedId === s.id ? (
                    <Check className="h-3.5 w-3.5 text-green-500" />
                  ) : (
                    <Copy className="h-3.5 w-3.5" />
                  )}
                </button>
              </div>
            ),
          },
          {
            key: "created",
            header: "Created",
            render: (s) => (
              <span className="text-sm text-[var(--text-secondary)]">
                {new Date(s.createdAt).toLocaleDateString()}
              </span>
            ),
            className: "w-32",
          },
        ]}
      />

      <ConfirmDialog
        open={confirmOpen}
        title="Delete School"
        description={
          schoolToDelete
            ? `Are you sure you want to delete "${schoolToDelete.name}"? This will unassign all students from this school. This action cannot be undone.`
            : undefined
        }
        confirmLabel="Delete"
        cancelLabel="Cancel"
        danger
        isPending={deletingId !== null}
        onConfirm={handleConfirmDelete}
        onCancel={handleCancelDelete}
      />
    </div>
  );
}

"use client";

import { createContext, useContext, useCallback, useMemo, useState, type ReactNode } from "react";
import { useAIChat } from "./hooks/use-ai-chat";
import { useAIPersistence } from "./hooks/use-ai-persistence";
import { detectCrisisKeywords } from "./utils/crisis-detection";
import type { AIContext, AIChatContextValue, ChatSession } from "./types";

const AIChatContext = createContext<AIChatContextValue | null>(null);

export function useAIChatContext(): AIChatContextValue {
  const context = useContext(AIChatContext);
  if (!context) {
    throw new Error("useAIChatContext must be used within AIChatProvider");
  }
  return context;
}

type AIChatProviderProps = {
  children: ReactNode;
  initialContext?: AIContext | null;
};

export function AIChatProvider({ children, initialContext = null }: AIChatProviderProps) {
  const persistence = useAIPersistence();

  const chat = useAIChat(
    initialContext?.chapterId,
    initialContext ? persistence.getChapterSessionId(initialContext.chapterId) : null
  );

  const [context, setContext] = useState<AIContext | null>(initialContext);

  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [isLoadingSessions, setIsLoadingSessions] = useState(true);

  const [showCrisisBanner, setShowCrisisBanner] = useState(false);

  const dismissCrisisBanner = useCallback(() => {
    setShowCrisisBanner(false);
  }, []);

  /**
   * Wraps the underlying chat.sendMessage so we can run client-side crisis
   * keyword detection BEFORE the message is sent (non-blocking — the message
   * still goes through regardless).
   */
  const sendMessageWithCrisisCheck = useCallback(
    async (content: string) => {
      if (detectCrisisKeywords(content)) {
        setShowCrisisBanner(true);
      }
      await chat.sendMessage(content);
    },
    [chat]
  );

  const updateContext = useCallback((newContext: Partial<AIContext>) => {
    setContext((prev) => (prev ? { ...prev, ...newContext } : null));
  }, []);

  const toggleVisibility = useCallback(() => {
    persistence.setVisibility(!persistence.isVisible);
  }, [persistence]);

  const toggleExpanded = useCallback(() => {
    persistence.setExpanded(!persistence.isExpanded);
  }, [persistence]);

  const toggleHistory = useCallback(() => {
    setIsHistoryOpen((prev) => !prev);
  }, []);

  const startNewSession = useCallback(() => {
    setShowCrisisBanner(false);
    chat.clearMessages();
    if (context?.chapterId) {
      persistence.setChapterSessionId(context.chapterId, null);
    }
  }, [chat, context, persistence]);

  const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL ?? "http://localhost:3001";

  const fetchSessionsList = useCallback(async () => {
    setIsLoadingSessions(true);
    try {
      const response = await fetch(`${backendUrl}/api/ai/sessions`, {
        method: "GET",
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to load sessions");
      const payload = (await response.json()) as { sessions: ChatSession[] };
      setSessions(payload.sessions ?? []);
    } catch {
      // Silently fail — sessions list is non-critical
    } finally {
      setIsLoadingSessions(false);
    }
  }, [backendUrl]);

  const refreshSessionsList = useCallback(
    async (preferredSessionId?: string | null) => {
      try {
        const response = await fetch(`${backendUrl}/api/ai/sessions`, {
          method: "GET",
          credentials: "include",
        });
        if (!response.ok) return;
        const payload = (await response.json()) as { sessions: ChatSession[] };
        const latestSessions = payload.sessions ?? [];
        setSessions(latestSessions);
      } catch {
        // Silently fail
      }
    },
    [backendUrl]
  );

  const loadSession = useCallback(
    async (sessionId: string) => {
      setIsLoadingSessions(true);
      try {
        const response = await fetch(`${backendUrl}/api/ai/sessions/${sessionId}/messages`, {
          credentials: "include",
        });
        if (!response.ok) throw new Error("Failed to load session");

        const payload = await response.json();
        const sessionMessages = payload.messages.map(
          (m: { id: string; role: "user" | "assistant"; content: string; createdAt: string }) => ({
            id: m.id,
            role: m.role,
            content: m.content,
          })
        );

        setShowCrisisBanner(false);
        chat.setMessagesFromSession(sessionMessages, sessionId);
      } catch {
        chat.clearError();
      } finally {
        setIsLoadingSessions(false);
        setIsHistoryOpen(false);
      }
    },
    [chat, backendUrl]
  );

  const value = useMemo<AIChatContextValue>(
    () => ({
      messages: chat.messages,
      sessionId: chat.sessionId,
      isStreaming: chat.isStreaming,
      isSending: chat.isSending,
      error: chat.error,
      stoppedStatus: chat.stoppedStatus,
      proactiveHint: chat.proactiveHint,

      rateLimitRemaining: chat.rateLimitRemaining,
      rateLimitTotal: chat.rateLimitTotal,

      context,
      updateContext,

      isVisible: persistence.isVisible,
      isExpanded: persistence.isExpanded,
      isHistoryOpen,
      isFirstVisit: persistence.isFirstVisit,

      showCrisisBanner,

      sessions,
      activeSessionId: chat.sessionId,
      isLoadingSessions,

      sendMessage: sendMessageWithCrisisCheck,
      stopGenerating: chat.stopGenerating,
      loadSession,
      startNewSession,
      toggleVisibility,
      toggleExpanded,
      toggleHistory,
      clearError: chat.clearError,
      dismissFirstVisit: persistence.dismissFirstVisit,
      dismissCrisisBanner,
      fetchSessionsList,
      refreshSessionsList,
    }),
    [
      chat.messages,
      chat.sessionId,
      chat.isStreaming,
      chat.isSending,
      chat.error,
      chat.stoppedStatus,
      chat.proactiveHint,
      chat.rateLimitRemaining,
      chat.rateLimitTotal,
      sendMessageWithCrisisCheck,
      chat.stopGenerating,
      chat.clearError,
      context,
      updateContext,
      persistence.isVisible,
      persistence.isExpanded,
      persistence.isFirstVisit,
      isHistoryOpen,
      showCrisisBanner,
      sessions,
      isLoadingSessions,
      loadSession,
      startNewSession,
      toggleVisibility,
      toggleExpanded,
      toggleHistory,
      persistence.dismissFirstVisit,
      dismissCrisisBanner,
      fetchSessionsList,
      refreshSessionsList,
    ]
  );

  return <AIChatContext.Provider value={value}>{children}</AIChatContext.Provider>;
}

