"use client";

import { useState, useEffect, useCallback } from "react";

type MobileKeyboardState = {
  /** Whether the virtual keyboard is currently visible */
  keyboardVisible: boolean;
  /** Estimated keyboard height in pixels (0 when hidden) */
  keyboardHeight: number;
  /** Current visual viewport height in pixels */
  viewportHeight: number;
};

/**
 * Detects mobile virtual keyboard presence using the Visual Viewport API.
 *
 * When the keyboard opens on mobile browsers the visual viewport shrinks while
 * the layout viewport stays the same. We compare `window.visualViewport.height`
 * to `window.innerHeight` to derive keyboard visibility and height.
 *
 * Falls back gracefully on browsers / environments without `visualViewport`.
 */
export function useMobileKeyboard(): MobileKeyboardState {
  const [state, setState] = useState<MobileKeyboardState>({
    keyboardVisible: false,
    keyboardHeight: 0,
    viewportHeight: 0,
  });

  const handleViewportChange = useCallback(() => {
    const vv = window.visualViewport;
    if (!vv) {
      setState((prev) => {
        if (
          prev.viewportHeight === window.innerHeight &&
          !prev.keyboardVisible &&
          prev.keyboardHeight === 0
        ) {
          return prev;
        }

        return {
          keyboardVisible: false,
          keyboardHeight: 0,
          viewportHeight: window.innerHeight,
        };
      });
      return;
    }

    // The difference between the layout viewport height (innerHeight) and the
    // visual viewport height tells us how much space the keyboard occupies.
    // We use a small threshold (150px) to avoid false positives from browser
    // chrome changes (URL bar hiding, etc.).
    const heightDiff = window.innerHeight - vv.height;
    const KEYBOARD_THRESHOLD = 150;

    const visible = heightDiff > KEYBOARD_THRESHOLD;
    const nextKeyboardHeight = visible ? heightDiff : 0;
    const nextViewportHeight = Math.round(vv.height);

    setState((prev) => {
      if (
        prev.keyboardVisible === visible &&
        prev.keyboardHeight === nextKeyboardHeight &&
        prev.viewportHeight === nextViewportHeight
      ) {
        return prev; // no change — avoid re-render
      }

      return {
        keyboardVisible: visible,
        keyboardHeight: nextKeyboardHeight,
        viewportHeight: nextViewportHeight,
      };
    });
  }, []);

  useEffect(() => {
    const vv = window.visualViewport;
    if (vv) {
      vv.addEventListener("resize", handleViewportChange);
      vv.addEventListener("scroll", handleViewportChange);
    }

    window.addEventListener("resize", handleViewportChange);
    handleViewportChange();

    return () => {
      if (vv) {
        vv.removeEventListener("resize", handleViewportChange);
        vv.removeEventListener("scroll", handleViewportChange);
      }

      window.removeEventListener("resize", handleViewportChange);
    };
  }, [handleViewportChange]);

  return state;
}

"use client";

import { useCallback, useMemo, useState } from "react";
import type { Components } from "react-markdown";
import ReactMarkdown from "react-markdown";
import remarkMath from "remark-math";
import remarkGfm from "remark-gfm";
import remarkBreaks from "remark-breaks";
import rehypeKatex from "rehype-katex";
import rehypeRaw from "rehype-raw";
import rehypeSanitize from "rehype-sanitize";
import rehypeHighlight from "rehype-highlight";

import { markdownSanitizeSchema } from "@/lib/markdown-sanitize-schema";
import { cva } from "class-variance-authority";
import { Check, Copy, ExternalLink } from "lucide-react";

import { cn } from "@/lib/utils";

/** Props for the markdown + math content rendering pipeline. */
export interface ContentRendererProps {
  /** Raw markdown string to render. */
  content: string;
  /** Rendering variant controlling spacing density. */
  variant?: "default" | "compact" | "ai-message";
  /** Enable LaTeX math rendering with KaTeX (inline $ and block $$). */
  enableMath?: boolean;
  /** Enable syntax-highlighted code blocks. */
  enableCode?: boolean;
  /** Enable GitHub Flavored Markdown (tables, strikethrough, task lists). */
  enableGfm?: boolean;
  /** Additional CSS class names for the root wrapper. */
  className?: string;
}

/* ─── CVA variant styles ─── */
const contentVariants = cva("md-root leading-relaxed", {
  variants: {
    variant: {
      default: "text-base [&>*:first-child]:mt-0 [&>*:last-child]:mb-0",
      compact:
        "text-sm [&>*:first-child]:mt-0 [&>*:last-child]:mb-0 [&_p]:my-1.5 [&_ul]:my-1.5 [&_ol]:my-1.5",
      "ai-message": "text-[0.9375rem] [&>*:first-child]:mt-0 [&>*:last-child]:mb-0 [&_p]:my-2",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

/* ─── Code-block copy button (used inside fenced code blocks) ─── */
function CopyButton({ code }: { code: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard may be unavailable */
    }
  }, [code]);

  return (
    <button
      type="button"
      onClick={handleCopy}
      className={cn(
        "absolute top-2 right-2 z-10 flex items-center gap-1 rounded-md px-2 py-1",
        "text-xs font-medium transition",
        "text-white/60 hover:text-white hover:bg-white/10",
        "opacity-0 group-hover:opacity-100 focus:opacity-100",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-primary/40"
      )}
      aria-label={copied ? "Copied to clipboard" : "Copy code to clipboard"}
    >
      {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
      <span>{copied ? "Copied" : "Copy"}</span>
    </button>
  );
}

/**
 * Full markdown + math rendering pipeline.
 *
 * Supports KaTeX math (inline/block), GFM tables, task lists, code fences
 * with syntax highlighting, and responsive styling via CSS variable tokens.
 */
export function ContentRenderer({
  content,
  variant = "default",
  enableMath = true,
  enableCode = true,
  enableGfm = true,
  className,
}: ContentRendererProps) {
  /* ─── Build plugin arrays dynamically ─── */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  type UnifiedPlugin = NonNullable<Parameters<typeof ReactMarkdown>[0]["remarkPlugins"]>[number];

  const remarkPlugins = useMemo(() => {
    const plugins: UnifiedPlugin[] = [remarkBreaks as UnifiedPlugin];
    if (enableMath) plugins.push(remarkMath as UnifiedPlugin);
    if (enableGfm) plugins.push(remarkGfm as UnifiedPlugin);
    return plugins;
  }, [enableMath, enableGfm]);

  const rehypePlugins = useMemo(() => {
    // rehype-sanitize MUST run immediately after rehype-raw so that any raw
    // HTML (including from user-submitted forum/notes/AI content) has scripts,
    // event handlers, and javascript: URLs stripped before rendering.
    const plugins: UnifiedPlugin[] = [
      rehypeRaw as UnifiedPlugin,
      [rehypeSanitize, markdownSanitizeSchema] as unknown as UnifiedPlugin,
    ];
    if (enableMath) plugins.push(rehypeKatex as UnifiedPlugin);
    if (enableCode) plugins.push(rehypeHighlight as UnifiedPlugin);
    return plugins;
  }, [enableMath, enableCode]);

  /* ─── Custom component overrides ─── */
  const components = useMemo<Components>(
    () => ({
      /* ── Headings (Syne / font-display) ── */
      h1: ({ children, ...props }) => (
        <h1
          className="md-h1 font-display text-3xl font-bold tracking-tight text-text-primary mt-8 mb-4 first:mt-0"
          {...props}
        >
          {children}
        </h1>
      ),
      h2: ({ children, ...props }) => (
        <h2
          className="md-h2 font-display text-2xl font-bold tracking-tight text-text-primary mt-7 mb-3 first:mt-0"
          {...props}
        >
          {children}
        </h2>
      ),
      h3: ({ children, ...props }) => (
        <h3
          className="md-h3 font-display text-xl font-semibold tracking-tight text-text-primary mt-6 mb-2 first:mt-0"
          {...props}
        >
          {children}
        </h3>
      ),
      h4: ({ children, ...props }) => (
        <h4
          className="md-h4 font-display text-lg font-semibold text-text-primary mt-5 mb-2 first:mt-0"
          {...props}
        >
          {children}
        </h4>
      ),
      h5: ({ children, ...props }) => (
        <h5
          className="md-h5 font-display text-base font-semibold text-text-primary mt-4 mb-1 first:mt-0"
          {...props}
        >
          {children}
        </h5>
      ),
      h6: ({ children, ...props }) => (
        <h6
          className="md-h6 font-display text-sm font-semibold uppercase tracking-wider text-text-secondary mt-4 mb-1 first:mt-0"
          {...props}
        >
          {children}
        </h6>
      ),

      /* ── Paragraph ── */
      p: ({ children, ...props }) => (
        <p className="md-p my-3 text-text-primary leading-relaxed" {...props}>
          {children}
        </p>
      ),

      /* ── Links ── */
      a: ({ href, children, ...props }) => {
        const isExternal = href?.startsWith("http://") || href?.startsWith("https://");

        return (
          <a
            href={href}
            className="md-a inline-flex items-center gap-0.5 text-accent-primary underline underline-offset-2 decoration-accent-primary/40 hover:decoration-accent-primary transition-colors"
            {...(isExternal ? { target: "_blank", rel: "noopener noreferrer" } : {})}
            {...props}
          >
            {children}
            {isExternal ? <ExternalLink className="inline h-3 w-3 shrink-0" /> : null}
          </a>
        );
      },

      /* ── Strong / Emphasis / Strikethrough ── */
      strong: ({ children, ...props }) => (
        <strong className="md-strong font-semibold text-text-primary" {...props}>
          {children}
        </strong>
      ),
      em: ({ children, ...props }) => (
        <em className="md-em italic" {...props}>
          {children}
        </em>
      ),
      del: ({ children, ...props }) => (
        <del className="md-del line-through text-text-muted" {...props}>
          {children}
        </del>
      ),

      /* ── Inline code ── */
      code: ({ className: codeClassName, children, ...props }) => {
        // Fenced code blocks get a className like "language-xxx" from rehype-highlight
        const match = /language-(\w+)/.exec(codeClassName ?? "");

        if (match) {
          const lang = match[1] ?? "text";
          const codeString = String(children).replace(/\n$/, "");

          return (
            <div className="group relative my-4 rounded-lg border border-border-default overflow-hidden">
              {/* Header */}
              <div className="flex items-center justify-between bg-[#1e1e2e] px-4 py-2 border-b border-white/[0.06]">
                <span className="rounded bg-white/10 px-2 py-0.5 font-mono text-xs uppercase tracking-wider text-white/70">
                  {lang}
                </span>
                <CopyButton code={codeString} />
              </div>
              {/* Code body */}
              <pre className="!m-0 !rounded-none overflow-x-auto bg-[#1e1e2e] p-4">
                <code className={cn(codeClassName, "font-mono text-sm leading-relaxed")} {...props}>
                  {children}
                </code>
              </pre>
            </div>
          );
        }

        // Inline code
        return (
          <code
            className="md-inline-code rounded bg-bg-subtle px-1.5 py-0.5 font-mono text-[0.875em] text-text-primary"
            {...props}
          >
            {children}
          </code>
        );
      },

      /* ── Preformatted (fallback for code without language) ── */
      pre: ({ children, ...props }) => {
        // If the child is already a fenced code block rendered above, just pass through
        return (
          <pre className="md-pre" {...props}>
            {children}
          </pre>
        );
      },

      /* ── Blockquote ── */
      blockquote: ({ children, ...props }) => (
        <blockquote
          className="md-blockquote my-4 rounded-r-lg border-l-4 border-accent-primary bg-bg-subtle/50 px-4 py-3 text-text-secondary"
          {...props}
        >
          {children}
        </blockquote>
      ),

      /* ── Lists ── */
      ul: ({ children, className: ulClassName, ...props }) => {
        // GFM task lists get a "contains-task-list" class
        const isTaskList = ulClassName?.includes("contains-task-list");
        return (
          <ul
            className={cn(
              "md-ul my-3 space-y-1",
              isTaskList ? "list-none pl-0" : "list-disc pl-6",
              ulClassName
            )}
            {...props}
          >
            {children}
          </ul>
        );
      },
      ol: ({ children, ...props }) => (
        <ol className="md-ol my-3 list-decimal space-y-1 pl-6" {...props}>
          {children}
        </ol>
      ),
      li: ({ children, className: liClassName, ...props }) => {
        const isTask = liClassName?.includes("task-list-item");
        return (
          <li
            className={cn(
              "md-li text-text-primary",
              isTask && "md-task-list-item flex items-start gap-2",
              liClassName
            )}
            {...props}
          >
            {children}
          </li>
        );
      },

      /* ── Task list checkbox ── */
      input: ({ type, checked, ...props }) => {
        if (type === "checkbox") {
          return (
            <span
              className={cn(
                "mt-1 inline-flex h-4 w-4 shrink-0 items-center justify-center rounded border-2 transition",
                checked
                  ? "border-accent-primary bg-accent-primary"
                  : "border-border-strong bg-transparent"
              )}
              role="checkbox"
              aria-checked={checked}
              {...props}
            >
              {checked ? (
                <svg
                  className="h-3 w-3 text-white"
                  viewBox="0 0 12 12"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M2.5 6l2.5 2.5 4.5-5" />
                </svg>
              ) : null}
            </span>
          );
        }
        return <input type={type} {...props} />;
      },

      /* ── Horizontal rule ── */
      hr: (props) => <hr className="md-hr my-8 border-t border-border-default" {...props} />,

      /* ── Table (responsive wrapper with alternating rows) ── */
      table: ({ children, ...props }) => (
        <div className="md-table-wrapper my-4 overflow-x-auto rounded-lg border border-border-default">
          <table className="md-table w-full border-collapse text-sm" {...props}>
            {children}
          </table>
        </div>
      ),
      thead: ({ children, ...props }) => (
        <thead className="md-thead bg-bg-subtle" {...props}>
          {children}
        </thead>
      ),
      th: ({ children, ...props }) => (
        <th
          className="md-th whitespace-nowrap border-b-2 border-border-default px-4 py-2.5 text-left text-xs font-semibold uppercase tracking-wider text-text-secondary"
          {...props}
        >
          {children}
        </th>
      ),
      tbody: ({ children, ...props }) => <tbody {...props}>{children}</tbody>,
      tr: ({ children, ...props }) => (
        <tr className="md-tr even:bg-bg-subtle/40" {...props}>
          {children}
        </tr>
      ),
      td: ({ children, ...props }) => (
        <td
          className="md-td border-b border-border-default px-4 py-2.5 text-text-primary"
          {...props}
        >
          {children}
        </td>
      ),

      /* ── Image ── */
      img: ({ src, alt, ...props }) => (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt ?? ""}
          className="md-img my-4 max-w-full rounded-lg border border-border-default"
          loading="lazy"
          {...props}
        />
      ),
    }),
    []
  );

  return (
    <div className={cn(contentVariants({ variant }), className)}>
      <ReactMarkdown
        remarkPlugins={remarkPlugins}
        rehypePlugins={rehypePlugins}
        components={components}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";

import { cn } from "@/lib/utils";

/**
 * Column breakpoint configuration for responsive grid layouts.
 * Each key defines the column count at that Tailwind breakpoint.
 */
export interface GridColumns {
  /** Columns at ≥640px (small screens). */
  sm: number;
  /** Columns at ≥768px (medium screens). */
  md: number;
  /** Columns at ≥1024px (large screens). */
  lg: number;
  /** Columns at ≥1280px (extra-large screens). */
  xl: number;
}

/**
 * Props for the virtualized grid component.
 *
 * @typeParam T - The type of each item in the data array.
 */
export interface VirtualGridProps<T> {
  /** Array of data items to render. */
  items: T[];
  /** Number of columns at each responsive breakpoint. */
  columns: GridColumns;
  /** Estimated pixel height for each row (used before measurement). */
  estimateHeight: number;
  /** Render function called for each visible item. */
  renderItem: (item: T, index: number) => ReactNode;
  /** Gap in pixels between grid cells. */
  gap?: number;
  /** Additional CSS class names for the scroll container. */
  className?: string;
}

/* ─── Breakpoint constants (Tailwind defaults) ─── */
const BREAKPOINTS = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
} as const;

/**
 * Returns the number of columns appropriate for the given viewport width.
 */
function getColumnsForWidth(width: number, columns: GridColumns): number {
  if (width >= BREAKPOINTS.xl) return columns.xl;
  if (width >= BREAKPOINTS.lg) return columns.lg;
  if (width >= BREAKPOINTS.md) return columns.md;
  if (width >= BREAKPOINTS.sm) return columns.sm;
  // Below sm — single column
  return 1;
}

/**
 * High-performance virtualized grid built on @tanstack/react-virtual.
 * Responds to viewport width to adjust column count per breakpoint,
 * and virtualizes rows to keep DOM node count minimal.
 */
export function VirtualGrid<T>({
  items,
  columns,
  estimateHeight,
  renderItem,
  gap = 16,
  className,
}: VirtualGridProps<T>) {
  const parentRef = useRef<HTMLDivElement>(null);
  const [columnCount, setColumnCount] = useState<number>(columns.md);

  /* ─── Responsive column count ─── */
  useEffect(() => {
    const el = parentRef.current;
    if (!el) return;

    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const width = entry.contentRect.width;
        setColumnCount(getColumnsForWidth(width, columns));
      }
    });

    // Initial measurement
    setColumnCount(getColumnsForWidth(el.clientWidth, columns));
    observer.observe(el);

    return () => observer.disconnect();
  }, [columns]);

  /* ─── Chunk items into rows ─── */
  const rows = useMemo(() => {
    const result: Array<Array<{ item: T; index: number }>> = [];
    for (let i = 0; i < items.length; i += columnCount) {
      const row: Array<{ item: T; index: number }> = [];
      for (let j = 0; j < columnCount && i + j < items.length; j++) {
        const item = items[i + j];
        if (item !== undefined) {
          row.push({ item, index: i + j });
        }
      }
      result.push(row);
    }
    return result;
  }, [items, columnCount]);

  /* ─── Virtualizer ─── */
  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => estimateHeight + gap,
    overscan: 3,
  });

  const virtualRows = virtualizer.getVirtualItems();

  return (
    <div ref={parentRef} className={cn("overflow-auto scrollbar-thin", className)}>
      <div className="relative w-full" style={{ height: `${virtualizer.getTotalSize()}px` }}>
        {virtualRows.map((virtualRow) => {
          const row = rows[virtualRow.index];
          if (!row) return null;

          return (
            <div
              key={virtualRow.key}
              data-index={virtualRow.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full"
              style={{
                transform: `translateY(${virtualRow.start}px)`,
                paddingBottom: `${gap}px`,
              }}
            >
              <div
                className="grid"
                style={{
                  gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
                  gap: `${gap}px`,
                }}
              >
                {row.map(({ item, index }) => (
                  <div key={index}>{renderItem(item, index)}</div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, type ReactNode } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";

import { cn } from "@/lib/utils";

/**
 * Props for the virtualized list component.
 * Renders only the visible items in the viewport for high-performance scrolling.
 *
 * @typeParam T - The type of each item in the data array.
 */
export interface VirtualListProps<T> {
  /** Array of data items to render. */
  items: T[];
  /** Estimated pixel height for each row (used before measurement). */
  estimateSize: number;
  /** Render function called for each visible item. */
  renderItem: (item: T, index: number) => ReactNode;
  /** Number of items to render outside the visible area for smoother scrolling. */
  overscan?: number;
  /** Additional CSS class names for the scroll container. */
  className?: string;
  /** Content shown when the items array is empty and not loading. */
  emptyState?: ReactNode;
  /** Content shown while data is being fetched. */
  loadingState?: ReactNode;
  /** Whether the list is in a loading state. */
  isLoading?: boolean;
  /** Callback fired when the user scrolls near the bottom of the list. */
  onEndReached?: () => void;
  /** Pixel distance from the bottom at which onEndReached fires. */
  endReachedThreshold?: number;
}

/**
 * High-performance virtualized list built on @tanstack/react-virtual.
 * Supports variable-height items via `measureElement`, infinite scroll via
 * `onEndReached`, and optional loading/empty states.
 */
export function VirtualList<T>({
  items,
  estimateSize,
  renderItem,
  overscan = 5,
  className,
  emptyState,
  loadingState,
  isLoading = false,
  onEndReached,
  endReachedThreshold = 200,
}: VirtualListProps<T>) {
  const parentRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => estimateSize,
    overscan,
  });

  const virtualItems = virtualizer.getVirtualItems();

  /* ─── Infinite scroll detection ─── */
  const handleScroll = useCallback(() => {
    const el = parentRef.current;
    if (!el || !onEndReached) return;

    const { scrollTop, scrollHeight, clientHeight } = el;
    if (scrollHeight - scrollTop - clientHeight <= endReachedThreshold) {
      onEndReached();
    }
  }, [onEndReached, endReachedThreshold]);

  useEffect(() => {
    const el = parentRef.current;
    if (!el || !onEndReached) return;

    el.addEventListener("scroll", handleScroll, { passive: true });
    return () => el.removeEventListener("scroll", handleScroll);
  }, [handleScroll, onEndReached]);

  /* ─── Loading state ─── */
  if (isLoading && items.length === 0) {
    return (
      <div className={cn("flex items-center justify-center p-8", className)}>
        {loadingState ?? (
          <div className="flex items-center gap-2 text-text-secondary">
            <div className="h-5 w-5 animate-spin rounded-full border-2 border-accent-primary border-t-transparent" />
            <span className="text-sm">Loading...</span>
          </div>
        )}
      </div>
    );
  }

  /* ─── Empty state ─── */
  if (!isLoading && items.length === 0) {
    return (
      <div className={cn("flex items-center justify-center p-8", className)}>
        {emptyState ?? <p className="text-sm text-text-muted">No items to display</p>}
      </div>
    );
  }

  return (
    <div ref={parentRef} className={cn("overflow-auto scrollbar-thin", className)}>
      <div className="relative w-full" style={{ height: `${virtualizer.getTotalSize()}px` }}>
        {virtualItems.map((virtualItem) => {
          const item = items[virtualItem.index];
          if (item === undefined) return null;

          return (
            <div
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement}
              className="absolute left-0 top-0 w-full"
              style={{
                transform: `translateY(${virtualItem.start}px)`,
              }}
            >
              {renderItem(item, virtualItem.index)}
            </div>
          );
        })}
      </div>

      {/* Bottom loading indicator for infinite scroll */}
      {isLoading && items.length > 0 ? (
        <div className="flex items-center justify-center py-4">
          {loadingState ?? (
            <div className="flex items-center gap-2 text-text-secondary">
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-accent-primary border-t-transparent" />
              <span className="text-xs">Loading more...</span>
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useCallback } from "react";
import { useRouter } from "next/navigation";

import { ErrorState } from "@/components/ui/states";
import { ReviewNowWidget } from "@/components/dashboard/review-now-widget";
import { AiMemoryCard } from "@/components/dashboard/ai-memory-card";
import { FocusAreasWidget, type FocusAreaItem } from "@/components/dashboard/focus-areas-widget";
import { SubjectWeakAreasCard } from "@/components/dashboard/subject-weak-areas-card";
import { StudyGroupsPanel } from "@/components/dashboard/study-groups-panel";
import { StarredFormulasWidget } from "@/components/dashboard/starred-formulas-widget";
import { ContinueLearningCard } from "@/components/dashboard/continue-learning-card";
import { StreakXPCard } from "@/components/dashboard/streak-xp-card";
import { TodaysGoalCard } from "@/components/dashboard/todays-goal-card";
import { SubjectProgressGrid } from "@/components/dashboard/subject-progress-grid";
import { QuickActionsCard } from "@/components/dashboard/quick-actions-card";
import { WeeklyActivityCard } from "@/components/dashboard/weekly-activity-card";
import { RecentActivityCard } from "@/components/dashboard/recent-activity-card";
import { DashboardSkeleton } from "@/components/dashboard/dashboard-skeleton";
import type { DashboardSummaryResponse } from "@/lib/progress-api";
import type { StudyGroupsListResponse } from "@/lib/study-groups-api";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type SubjectSummary = DashboardSummaryResponse["subjects"][number];

export interface DashboardClientProps {
  displayName: string;
  summary: DashboardSummaryResponse | null;
  summaryError: string | null;
  featuredSubject: SubjectSummary | null;
  continueHref: string | null;
  orderedSubjects: SubjectSummary[];
  firstChapterBasePath: string | null;
  focusAreas: FocusAreaItem[];
  studyGroups: StudyGroupsListResponse["groups"];
}

/* ------------------------------------------------------------------ */
/*  Main DashboardClient component                                     */
/* ------------------------------------------------------------------ */

export function DashboardClient({
  summary,
  summaryError,
  featuredSubject,
  continueHref,
  orderedSubjects,
  firstChapterBasePath,
  focusAreas,
  studyGroups,
}: DashboardClientProps) {
  const router = useRouter();

  const handleRetry = useCallback(() => {
    router.refresh();
  }, [router]);

  if (summaryError && !summary) {
    return (
      <ErrorState
        title="Progress data is temporarily unavailable"
        description="We couldn't load your dashboard data right now. Please try again in a moment."
        onRetry={handleRetry}
        retryLabel="Retry"
      />
    );
  }

  if (!summary) {
    return <DashboardSkeleton />;
  }

  const hasFocusAreas = focusAreas.length > 0;
  const hasStarredFormulas = summary.starredFormulas.length > 0;
  const hasWeakAreas = orderedSubjects.some((s) => s.weakAreas.length > 0);

  return (
    <div className="space-y-8">
      {/* ============================================================ */}
      {/*  HERO ZONE — Equal columns, no spanning                      */}
      {/* ============================================================ */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <ContinueLearningCard subject={featuredSubject} continueHref={continueHref} />
        <StreakXPCard
          streakDays={summary.streakDays}
          longestStreakDays={summary.longestStreakDays}
          xp={summary.xp}
          summary={summary}
        />
        <TodaysGoalCard summary={summary} />
      </div>

      {/* ============================================================ */}
      {/*  MAIN CONTENT — Subject progress (full width)                */}
      {/* ============================================================ */}
      <SubjectProgressGrid subjects={orderedSubjects} />

      {/* ============================================================ */}
      {/*  INSIGHTS + SIDEBAR — Weak areas + Widgets                   */}
      {/* ============================================================ */}
      <div className="grid gap-4 lg:grid-cols-2 xl:grid-cols-3 items-start">
        <div className="xl:col-span-2">
          <SubjectWeakAreasCard subjects={orderedSubjects} />
        </div>

        <div className="flex flex-col gap-4">
          {hasFocusAreas ? <FocusAreasWidget recommendations={focusAreas} /> : null}
          <ReviewNowWidget />
        </div>
      </div>

      {/* ============================================================ */}
      {/*  WIDGETS ROW — Formulas, Quick Actions, AI Memory            */}
      {/* ============================================================ */}
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3 items-start">
        {hasStarredFormulas ? <StarredFormulasWidget formulas={summary.starredFormulas} /> : null}
        <QuickActionsCard firstChapterBasePath={firstChapterBasePath} />
        <AiMemoryCard />
      </div>

      {/* ============================================================ */}
      {/*  ACTIVITY — Weekly heatmap + Recent timeline                  */}
      {/* ============================================================ */}
      <div className="grid gap-4 sm:grid-cols-2">
        <WeeklyActivityCard weeklyActivity={summary.weeklyActivity} />
        <RecentActivityCard activity={summary.recentActivity} />
      </div>

      {/* ============================================================ */}
      {/*  STUDY GROUPS — Full width at bottom                         */}
      {/* ============================================================ */}
      <StudyGroupsPanel groups={studyGroups} />
    </div>
  );
}

