"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { motion } from "framer-motion";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ThumbsUp, ThumbsDown, CheckCircle, Award } from "lucide-react";
import { z } from "zod";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useToast } from "@/components/ui/toast";
import { ForumApiError, forumKeys } from "@/lib/forum-api";
import { cn } from "@/lib/utils";

const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL ?? "http://localhost:3001";

type ForumReplyActionsProps = {
  replyId: string;
  upvotes: number;
  viewerVoteType: "upvote" | "downvote" | null;
  isAcceptedAnswer: boolean;
  canMarkAccepted: boolean;
  isAuthenticated: boolean;
};

const errorSchema = z.object({
  error: z.string(),
});

const postForumReplyAction = async (
  url: string,
  init?: RequestInit,
  fallbackMessage = "Request failed."
): Promise<void> => {
  const response = await fetch(url, {
    method: "POST",
    credentials: "include",
    ...init,
  });
  const responseBody = (await response.json().catch(() => null)) as unknown;

  if (!response.ok) {
    const parsedError = errorSchema.safeParse(responseBody);
    throw new ForumApiError(
      parsedError.success ? parsedError.data.error : fallbackMessage
    );
  }
};

export const ForumReplyActions = ({
  replyId,
  upvotes,
  viewerVoteType,
  isAcceptedAnswer,
  canMarkAccepted,
  isAuthenticated,
}: ForumReplyActionsProps) => {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { pushToast } = useToast();
  const [error, setError] = useState<string | null>(null);

  const onError = (mutationError: Error, fallbackMessage: string) => {
    if (mutationError instanceof ForumApiError) {
      setError(mutationError.message);
      return;
    }
    setError("Network error. Check your connection and try again.");
    pushToast({
      title: fallbackMessage,
      description: "The server could not be reached. Please try again.",
      tone: "error",
    });
  };

  const voteMutation = useMutation({
    mutationFn: async (voteType: "upvote" | "downvote") => {
      await postForumReplyAction(
        `${backendUrl}/api/forum/replies/${replyId}/vote`,
        {
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ voteType }),
        },
        "Vote failed."
      );
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: forumKeys.all });
      router.refresh();
    },
    onError: (mutationError) => onError(mutationError, "Vote failed"),
  });

  const acceptMutation = useMutation({
    mutationFn: async () => {
      await postForumReplyAction(
        `${backendUrl}/api/forum/replies/${replyId}/accept`,
        undefined,
        "Accept answer failed."
      );
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: forumKeys.all });
      router.refresh();
    },
    onError: (mutationError) => onError(mutationError, "Accept answer failed"),
  });

  const isPending = voteMutation.isPending || acceptMutation.isPending;

  return (
    <div className="mt-3 space-y-1.5">
      <div className="flex flex-wrap items-center gap-1.5">
        {/* Upvote button */}
        <button
          type="button"
          disabled={isPending}
          onClick={() => {
            if (!isAuthenticated) {
              setError("Sign in to vote.");
              return;
            }
            setError(null);
            voteMutation.mutate("upvote");
          }}
          className={cn(
            "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all duration-150",
            "border focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-primary/40",
            "disabled:pointer-events-none disabled:opacity-50",
            viewerVoteType === "upvote"
              ? "border-accent-success/30 bg-accent-success-light text-accent-success"
              : "border-border-default bg-bg-subtle text-text-secondary hover:border-accent-success/30 hover:text-accent-success"
          )}
          aria-label="Upvote"
          aria-pressed={viewerVoteType === "upvote"}
        >
          <ThumbsUp className="h-3 w-3" aria-hidden="true" />
          <span>Upvote</span>
        </button>

        {/* Score */}
        <span
          className={cn(
            "px-1.5 text-xs font-bold tabular-nums",
            upvotes > 0
              ? "text-accent-success"
              : upvotes < 0
                ? "text-accent-danger"
                : "text-text-muted"
          )}
        >
          {upvotes > 0 ? `+${upvotes}` : upvotes}
        </span>

        {/* Downvote button */}
        <button
          type="button"
          disabled={isPending}
          onClick={() => {
            if (!isAuthenticated) {
              setError("Sign in to vote.");
              return;
            }
            setError(null);
            voteMutation.mutate("downvote");
          }}
          className={cn(
            "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all duration-150",
            "border focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-primary/40",
            "disabled:pointer-events-none disabled:opacity-50",
            viewerVoteType === "downvote"
              ? "border-accent-danger/30 bg-accent-danger-light text-accent-danger"
              : "border-border-default bg-bg-subtle text-text-secondary hover:border-accent-danger/30 hover:text-accent-danger"
          )}
          aria-label="Downvote"
          aria-pressed={viewerVoteType === "downvote"}
        >
          <ThumbsDown className="h-3 w-3" aria-hidden="true" />
        </button>

        {/* Separator */}
        <span className="h-4 w-px bg-border-default" aria-hidden="true" />

        {/* Accept answer button */}
        {canMarkAccepted && !isAcceptedAnswer ? (
          <button
            type="button"
            disabled={isPending}
            onClick={() => {
              if (!isAuthenticated) {
                setError("Sign in to mark an accepted answer.");
                return;
              }
              setError(null);
              acceptMutation.mutate();
            }}
            className={cn(
              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all duration-150",
              "border border-border-default bg-bg-subtle text-text-secondary",
              "hover:border-accent-success/30 hover:bg-accent-success-light hover:text-accent-success",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-primary/40",
              "disabled:pointer-events-none disabled:opacity-50"
            )}
            aria-label="Mark as accepted answer"
          >
            <Award className="h-3 w-3" aria-hidden="true" />
            <span>Accept</span>
          </button>
        ) : null}
      </div>

      {/* Error */}
      {error ? (
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-xs text-accent-danger"
        >
          {error}
        </motion.p>
      ) : null}
    </div>
  );
};

"use client";

import { motion } from "framer-motion";
import { CheckCircle, Clock, MessageSquare } from "lucide-react";

import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { ContentRenderer } from "@/components/common/content-renderer";
import { EmptyState } from "@/components/ui/states";
import type { ForumThreadDetailResponse } from "@/lib/forum-api";

import { ForumReplyActions } from "./forum-reply-actions";
import { ForumReplyForm } from "./forum-reply-form";

type ThreadReplies = ForumThreadDetailResponse["thread"]["replies"];

const formatRelativeTime = (value: string): string => {
  const now = Date.now();
  const date = new Date(value).getTime();
  const diff = now - date;
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (days > 30) {
    return new Date(value).toLocaleString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  }
  if (days > 0) {
    return `${days}d ago`;
  }
  if (hours > 0) {
    return `${hours}h ago`;
  }
  if (minutes > 0) {
    return `${minutes}m ago`;
  }
  return "just now";
};

type ForumReplyListProps = {
  threadId: string;
  replies: ThreadReplies;
  canMarkAccepted: boolean;
  isAuthenticated: boolean;
};

export function ForumReplyList({
  threadId,
  replies,
  canMarkAccepted,
  isAuthenticated,
}: ForumReplyListProps) {
  if (replies.length === 0) {
    return (
      <EmptyState
        title="No replies yet"
        description="Be the first to answer this question."
        icon={<MessageSquare className="h-5 w-5" aria-hidden="true" />}
      />
    );
  }

  return (
    <section className="space-y-3" aria-label="Replies">
      {replies.map((reply, index) => (
        <motion.article
          key={reply.id}
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: Math.min(index * 0.05, 0.5), ease: "easeOut" }}
          className={[
            "rounded-xl border bg-bg-surface overflow-hidden transition-colors",
            reply.isAcceptedAnswer
              ? "border-accent-success/40 ring-1 ring-accent-success/20"
              : "border-border-default",
          ].join(" ")}
        >
          {/* Accepted answer banner */}
          {reply.isAcceptedAnswer ? (
            <div className="flex items-center gap-2 border-b border-accent-success/20 bg-accent-success-light px-5 py-2">
              <CheckCircle className="h-3.5 w-3.5 text-accent-success" aria-hidden="true" />
              <span className="text-xs font-bold text-accent-success">Accepted Answer</span>
            </div>
          ) : null}

          <div className="p-5">
            {/* Author row */}
            <div className="flex items-center gap-3">
              <Avatar name={reply.userName} size="sm" />
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-sm font-semibold text-text-primary">{reply.userName}</span>
                <span className="inline-flex items-center gap-1 text-xs text-text-muted">
                  <Clock className="h-3 w-3" aria-hidden="true" />
                  {formatRelativeTime(reply.createdAt)}
                </span>
              </div>
            </div>

            {/* Reply body */}
            <div className="mt-3 rounded-lg bg-bg-base/50 p-4">
              <ContentRenderer content={reply.body} variant="compact" />
            </div>

            {/* Vote actions */}
            <ForumReplyActions
              replyId={reply.id}
              upvotes={reply.upvotes}
              viewerVoteType={reply.viewerVoteType}
              isAcceptedAnswer={reply.isAcceptedAnswer}
              canMarkAccepted={canMarkAccepted}
              isAuthenticated={isAuthenticated}
            />

            {/* Nested replies */}
            {reply.replies.length > 0 ? (
              <div className="mt-4 space-y-2 border-l-2 border-border-default pl-4">
                {reply.replies.map((nestedReply, nestedIndex) => (
                  <motion.div
                    key={nestedReply.id}
                    initial={{ opacity: 0, x: -8 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.2, delay: nestedIndex * 0.03, ease: "easeOut" }}
                    className={[
                      "rounded-lg border p-4 transition-colors",
                      nestedReply.isAcceptedAnswer
                        ? "border-accent-success/30 bg-accent-success-light/50"
                        : "border-border-default bg-bg-subtle/40",
                    ].join(" ")}
                  >
                    {/* Nested accepted banner */}
                    {nestedReply.isAcceptedAnswer ? (
                      <div className="mb-2 flex items-center gap-1.5">
                        <CheckCircle className="h-3 w-3 text-accent-success" aria-hidden="true" />
                        <span className="text-[10px] font-bold text-accent-success">
                          Accepted Answer
                        </span>
                      </div>
                    ) : null}

                    {/* Author */}
                    <div className="flex items-center gap-2">
                      <Avatar name={nestedReply.userName} size="xs" />
                      <span className="text-xs font-semibold text-text-primary">
                        {nestedReply.userName}
                      </span>
                      <span className="inline-flex items-center gap-0.5 text-[10px] text-text-muted">
                        <Clock className="h-2.5 w-2.5" aria-hidden="true" />
                        {formatRelativeTime(nestedReply.createdAt)}
                      </span>
                    </div>

                    {/* Body */}
                    <div className="mt-2">
                      <ContentRenderer content={nestedReply.body} variant="compact" />
                    </div>

                    {/* Vote actions */}
                    <ForumReplyActions
                      replyId={nestedReply.id}
                      upvotes={nestedReply.upvotes}
                      viewerVoteType={nestedReply.viewerVoteType}
                      isAcceptedAnswer={nestedReply.isAcceptedAnswer}
                      canMarkAccepted={canMarkAccepted}
                      isAuthenticated={isAuthenticated}
                    />
                  </motion.div>
                ))}
              </div>
            ) : null}

            {/* Nested reply form */}
            {isAuthenticated ? (
              <ForumReplyForm threadId={threadId} parentReplyId={reply.id} compact />
            ) : null}
          </div>
        </motion.article>
      ))}
    </section>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { FormEvent, useMemo, useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { Eye, Pencil, X, Send, BookOpen, Layers } from "lucide-react";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/components/ui/toast";
import { ContentRenderer } from "@/components/common/content-renderer";
import {
  Sheet,
  SheetHeader,
  SheetBody,
  SheetFooter,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { Tabs, TabList, TabTrigger, TabContent } from "@/components/ui/tabs";
import { ForumApiError, forumKeys } from "@/lib/forum-api";

const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL ?? "http://localhost:3001";

const createThreadSchema = z.object({
  title: z.string().trim().min(5).max(160),
  body: z.string().trim().min(10),
  subjectId: z.number().int().positive().optional(),
  chapterId: z.number().int().positive().optional(),
});

const createThreadResponseSchema = z.object({
  thread: z.object({
    id: z.string().uuid(),
  }),
});

const threadErrorSchema = z.object({
  error: z.string(),
});

type CreateThreadInput = z.infer<typeof createThreadSchema>;

type ForumSubjectOption = {
  id: number;
  name: string;
  slug: string;
  grade: string | null;
  className: string | null;
  classSlug: string | null;
  boardId: number;
};

type ForumChapterOption = {
  id: number;
  title: string;
  slug: string;
  chapterNumber: number;
  subjectId: number;
};

type ForumThreadFormProps = {
  subjects: ForumSubjectOption[];
  chapters: ForumChapterOption[];
  isOpen: boolean;
  closeHref: string;
};

export const ForumThreadForm = ({
  subjects,
  chapters,
  isOpen,
  closeHref,
}: ForumThreadFormProps) => {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { pushToast } = useToast();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [subjectId, setSubjectId] = useState("");
  const [chapterId, setChapterId] = useState("");
  const [activeTab, setActiveTab] = useState("write");
  const [error, setError] = useState<string | null>(null);

  const filteredChapterOptions = useMemo(() => {
    if (!subjectId) {
      return [];
    }

    const selectedSubjectId = Number(subjectId);
    return chapters.filter((chapter) => chapter.subjectId === selectedSubjectId);
  }, [chapters, subjectId]);

  const onSubjectChange = (nextSubjectId: string) => {
    setSubjectId(nextSubjectId);
    if (!nextSubjectId) {
      setChapterId("");
      return;
    }

    const numericSubjectId = Number(nextSubjectId);
    const selectedChapter = chapterId ? Number(chapterId) : null;
    if (selectedChapter) {
      const chapterStillValid = chapters.some(
        (chapter) => chapter.id === selectedChapter && chapter.subjectId === numericSubjectId
      );
      if (!chapterStillValid) {
        setChapterId("");
      }
    }
  };

  const handleClose = () => {
    router.push(closeHref);
  };

  const submitMutation = useMutation({
    mutationFn: async (input: CreateThreadInput) => {
      const response = await fetch(`${backendUrl}/api/forum/threads`, {
        method: "POST",
        credentials: "include",
        headers: {
          "content-type": "application/json",
        },
        body: JSON.stringify(input),
      });
      const responseBody = (await response.json().catch(() => null)) as unknown;

      if (response.status === 401) {
        throw new ForumApiError("You must sign in before creating a thread.");
      }

      if (!response.ok) {
        const parsedError = threadErrorSchema.safeParse(responseBody);
        throw new ForumApiError(
          parsedError.success ? parsedError.data.error : "Thread creation failed."
        );
      }

      const parsedResponse = createThreadResponseSchema.safeParse(responseBody);
      if (!parsedResponse.success) {
        throw new ForumApiError("Thread was created but the response payload was invalid.");
      }

      return parsedResponse.data;
    },
    onSuccess: (data) => {
      setTitle("");
      setBody("");
      setSubjectId("");
      setChapterId("");
      void queryClient.invalidateQueries({ queryKey: forumKeys.all });
      router.push(`/forum/${data.thread.id}`);
      router.refresh();
    },
    onError: (mutationError) => {
      if (mutationError instanceof ForumApiError) {
        setError(mutationError.message);
        return;
      }
      setError("Network error. Check your connection and try again.");
      pushToast({
        title: "Failed to create thread",
        description: "The server could not be reached. Please try again.",
        tone: "error",
      });
    },
  });

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);

    const maybeSubjectId = subjectId ? Number(subjectId) : undefined;
    const maybeChapterId = chapterId ? Number(chapterId) : undefined;

    const parsed = createThreadSchema.safeParse({
      title,
      body,
      subjectId: maybeSubjectId,
      chapterId: maybeChapterId,
    });

    if (!parsed.success) {
      setError(parsed.error.issues[0]?.message ?? "Invalid thread input.");
      return;
    }

    submitMutation.mutate(parsed.data);
  };

  return (
    <Sheet
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) handleClose();
      }}
      side="right"
      className="!w-[480px] !max-w-[92vw]"
    >
      <SheetHeader>
        <SheetTitle>New Post</SheetTitle>
        <SheetDescription>Ask a question or share something with the community.</SheetDescription>
      </SheetHeader>

      <SheetBody>
        <form id="create-thread-form" onSubmit={onSubmit} className="space-y-5">
          {/* Title input */}
          <Input
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            maxLength={160}
            required
            label="Title"
            placeholder="What are you stuck on?"
            prefix={<Pencil />}
          />

          {/* Subject & Chapter selectors */}
          <div className="grid gap-4 sm:grid-cols-2">
            <label className="space-y-1.5">
              <span className="flex items-center gap-1.5 text-sm font-medium text-text-primary">
                <BookOpen className="h-3.5 w-3.5 text-text-muted" aria-hidden="true" />
                Subject
              </span>
              <Select
                value={subjectId}
                onChange={(event) => onSubjectChange(event.target.value)}
                className="!h-10 !text-sm"
              >
                <option value="">No subject tag</option>
                {subjects.map((subject) => (
                  <option key={subject.id} value={String(subject.id)}>
                    {subject.name}
                    {subject.className ? ` (${subject.className})` : ""}
                  </option>
                ))}
              </Select>
            </label>

            <label className="space-y-1.5">
              <span className="flex items-center gap-1.5 text-sm font-medium text-text-primary">
                <Layers className="h-3.5 w-3.5 text-text-muted" aria-hidden="true" />
                Chapter
              </span>
              <Select
                value={chapterId}
                onChange={(event) => setChapterId(event.target.value)}
                disabled={!subjectId}
                className="!h-10 !text-sm"
              >
                <option value="">No chapter tag</option>
                {filteredChapterOptions.map((chapter) => (
                  <option key={chapter.id} value={String(chapter.id)}>
                    Ch. {chapter.chapterNumber}: {chapter.title}
                  </option>
                ))}
              </Select>
            </label>
          </div>

          {/* Body editor with tabs */}
          <div className="space-y-1.5">
            <span className="block text-sm font-medium text-text-primary">Body</span>
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabList variant="pills" className="mb-3">
                <TabTrigger value="write" variant="pills" layoutId="compose-tab">
                  <Pencil className="h-3 w-3" aria-hidden="true" />
                  Write
                </TabTrigger>
                <TabTrigger value="preview" variant="pills" layoutId="compose-tab">
                  <Eye className="h-3 w-3" aria-hidden="true" />
                  Preview
                </TabTrigger>
              </TabList>

              <TabContent value="write">
                <Textarea
                  value={body}
                  onChange={(event) => setBody(event.target.value)}
                  required
                  rows={10}
                  placeholder="Add details, context, and what you've tried. Markdown & LaTeX supported."
                  autoResize
                  maxRows={20}
                />
                <p className="mt-1.5 text-[11px] text-text-muted">
                  Supports **bold**, *italic*, `code`, and $\LaTeX$ math.
                </p>
              </TabContent>

              <TabContent value="preview">
                <div className="min-h-[200px] rounded-lg border border-border-default bg-bg-base p-4">
                  {body.trim().length > 0 ? (
                    <ContentRenderer content={body} variant="default" />
                  ) : (
                    <p className="text-sm text-text-muted">
                      Nothing to preview yet. Start writing above.
                    </p>
                  )}
                </div>
              </TabContent>
            </Tabs>
          </div>

          {/* Error display */}
          <AnimatePresence>
            {error ? (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="overflow-hidden"
              >
                <div className="rounded-lg border border-accent-danger/20 bg-accent-danger-light px-4 py-3">
                  <p className="text-sm text-accent-danger">{error}</p>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </form>
      </SheetBody>

      <SheetFooter>
        <Button type="button" variant="ghost" size="sm" onClick={handleClose}>
          Cancel
        </Button>
        <Button
          type="submit"
          form="create-thread-form"
          variant="primary"
          size="sm"
          loading={submitMutation.isPending}
          iconLeft={<Send />}
        >
          {submitMutation.isPending ? "Posting..." : "Submit"}
        </Button>
      </SheetFooter>
    </Sheet>
  );
};

