"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { z } from "zod";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import {
  ChevronLeft,
  ChevronRight,
  SkipForward,
  Send,
  AlertTriangle,
  Swords,
  TimerReset,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { LinearProgress } from "@/components/ui/progress";
import { EmptyState } from "@/components/ui/states";
import type { ChapterDetailResponse } from "@/lib/learn-api";

import { QuizQuestionCard } from "./quiz-question-card";
import { QuizQuestionReviewList } from "./quiz-question-review-list";
import { QuizResultSummary } from "./quiz-result-summary";
import { QuizTimer } from "./quiz-timer";
import { QuestionNavigator } from "./question-navigator";
import { MockExamResultDetails } from "./mock-exam-result-details";
import { QUIZ_NAVIGATOR_THRESHOLD, TIMER_INTERVAL_MS } from "@/lib/quiz-constants";

type Quiz = NonNullable<ChapterDetailResponse["quiz"]>;
type AnswerOption = "a" | "b" | "c" | "d";

const submitQuizResponseSchema = z.object({
  attemptId: z.string().uuid(),
  quizId: z.number().int().positive(),
  quizType: z.enum(["chapter_quiz", "mock_exam"]),
  score: z.number().int().nonnegative(),
  totalMarks: z.number().int().positive(),
  percentage: z.number().int().min(0).max(100),
  timeSpentSeconds: z.number().int().nonnegative(),
  completedAt: z.string().datetime(),
  questionResults: z.array(
    z.object({
      questionId: z.number().int().positive(),
      question: z.string(),
      optionA: z.string(),
      optionB: z.string(),
      optionC: z.string(),
      optionD: z.string(),
      chapterId: z.number().int().positive().nullable(),
      chapterTitle: z.string().nullable(),
      selectedOption: z.enum(["a", "b", "c", "d"]).nullable(),
      correctOption: z.enum(["a", "b", "c", "d"]),
      isCorrect: z.boolean(),
      explanation: z.string(),
      marks: z.number().int().positive(),
      awardedMarks: z.number().int().nonnegative(),
    })
  ),
  sectionScores: z
    .array(
      z.object({
        chapterId: z.number().int().nullable(),
        chapterTitle: z.string().nullable(),
        chapterNumber: z.number().int().nullable(),
        score: z.number().int(),
        totalMarks: z.number().int(),
        questionCount: z.number().int(),
        correctCount: z.number().int(),
      })
    )
    .optional(),
  weakAreas: z
    .array(
      z.object({
        chapterId: z.number().int(),
        chapterTitle: z.string(),
        chapterNumber: z.number().int(),
        correctPercentage: z.number(),
        wrongQuestionCount: z.number().int(),
        totalQuestions: z.number().int(),
      })
    )
    .optional(),
  duel: z
    .object({
      challengeId: z.string().uuid(),
      status: z.enum(["open", "completed", "expired"]),
      expiresAt: z.string().datetime(),
      challenger: z.object({
        userId: z.string(),
        name: z.string(),
        score: z.number().int().nonnegative(),
        totalMarks: z.number().int().nonnegative(),
        percentage: z.number().int().min(0).max(100),
        completedAt: z.string().datetime(),
        isCurrentUser: z.boolean(),
      }),
      recipient: z
        .object({
          userId: z.string(),
          name: z.string(),
          score: z.number().int().nonnegative(),
          totalMarks: z.number().int().nonnegative(),
          percentage: z.number().int().min(0).max(100),
          completedAt: z.string().datetime(),
          isCurrentUser: z.boolean(),
        })
        .nullable(),
    })
    .optional(),
});

export type QuizResult = z.infer<typeof submitQuizResponseSchema>;

type QuizSubmitErrorResponse = {
  error?: string;
};

type QuizRunnerProps = {
  quiz: Quiz;
  subjectName?: string;
  chapterNumber?: number;
  chapterTitle?: string;
  challengeId?: string;
  onQuizComplete?: (score: number, percentage: number) => void;
};

const quizChallengeResponseSchema = z.object({
  data: z.object({
    challengeId: z.string().uuid(),
    quizId: z.number().int().positive(),
    expiresAt: z.string().datetime(),
    createdAt: z.string().datetime(),
  }),
});

const quizChallengeDetailResponseSchema = z.object({
  data: submitQuizResponseSchema.shape.duel.unwrap(),
});

/** Slide direction for the page transition */
type SlideDirection = "left" | "right";

const slideVariants = {
  enter: (direction: SlideDirection) => ({
    x: direction === "left" ? 300 : -300,
    opacity: 0,
  }),
  center: {
    x: 0,
    opacity: 1,
  },
  exit: (direction: SlideDirection) => ({
    x: direction === "left" ? -300 : 300,
    opacity: 0,
  }),
};

export function QuizRunner({
  quiz,
  subjectName,
  chapterNumber,
  chapterTitle,
  challengeId,
  onQuizComplete,
}: QuizRunnerProps) {
  const reduced = useReducedMotion();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, AnswerOption>>({});
  const [remainingSeconds, setRemainingSeconds] = useState(quiz.durationMinutes * 60);
  const [startedAtMs, setStartedAtMs] = useState(() => Date.now());
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [result, setResult] = useState<QuizResult | null>(null);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [announcementText, setAnnouncementText] = useState("");
  const [slideDirection, setSlideDirection] = useState<SlideDirection>("left");
  const [challengeError, setChallengeError] = useState<string | null>(null);
  const [challengeDetails, setChallengeDetails] = useState<QuizResult["duel"] | null>(null);

  const backendUrl = useMemo(
    () => process.env.NEXT_PUBLIC_BACKEND_URL ?? "http://localhost:3001",
    []
  );

  const currentQuestion = quiz.questions[currentIndex];
  const answeredCount = Object.keys(answers).length;
  const isMockExam = quiz.type === "mock_exam";
  const isTimeUp = remainingSeconds === 0;
  const totalQuestions = quiz.questions.length;
  const progressPercent = ((currentIndex + 1) / totalQuestions) * 100;
  const isChallengeMode = Boolean(challengeId);

  const selectAnswer = (questionId: number, option: AnswerOption) => {
    if (result || isSubmitting || isTimeUp) {
      return;
    }

    setAnswers((previous) => ({
      ...previous,
      [String(questionId)]: option,
    }));
  };

  const goToQuestion = useCallback(
    (newIndex: number) => {
      setSlideDirection(newIndex > currentIndex ? "left" : "right");
      setCurrentIndex(newIndex);
    },
    [currentIndex]
  );

  const goNext = useCallback(() => {
    if (currentIndex < totalQuestions - 1) {
      setSlideDirection("left");
      setCurrentIndex((prev) => prev + 1);
    }
  }, [currentIndex, totalQuestions]);

  const goPrevious = useCallback(() => {
    if (currentIndex > 0) {
      setSlideDirection("right");
      setCurrentIndex((prev) => prev - 1);
    }
  }, [currentIndex]);

  const skipQuestion = useCallback(() => {
    if (currentIndex < totalQuestions - 1) {
      setSlideDirection("left");
      setCurrentIndex((prev) => prev + 1);
    }
  }, [currentIndex, totalQuestions]);

  const submitQuiz = useCallback(async () => {
    if (result || isSubmitting) {
      return;
    }

    setIsSubmitting(true);
    setSubmitError(null);

    try {
      const response = await fetch(`${backendUrl}/api/quiz/submit`, {
        method: "POST",
        credentials: "include",
        headers: {
          "content-type": "application/json",
        },
        body: JSON.stringify({
          quizId: quiz.id,
          startedAt: new Date(startedAtMs).toISOString(),
          answers,
          challengeId,
        }),
      });

      if (!response.ok) {
        const payload = (await response.json().catch(() => null)) as QuizSubmitErrorResponse | null;
        setSubmitError(payload?.error ?? `Quiz submission failed with status ${response.status}.`);
        return;
      }

      const json = (await response.json()) as unknown;
      const parsedResponse = submitQuizResponseSchema.safeParse(json);
      if (!parsedResponse.success) {
        setSubmitError("Quiz submission response could not be parsed.");
        return;
      }

      const correctCount = parsedResponse.data.questionResults.filter((q) => q.isCorrect).length;
      const totalCount = parsedResponse.data.questionResults.length;
      setAnnouncementText(
        `Quiz complete! You got ${correctCount} out of ${totalCount} questions correct.`
      );
      setResult(parsedResponse.data);

      // Notify parent for gamification (XP, progress, streak)
      onQuizComplete?.(parsedResponse.data.score, parsedResponse.data.percentage);
    } catch {
      setSubmitError("Unable to submit quiz right now. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }, [
    answers,
    backendUrl,
    challengeId,
    isSubmitting,
    onQuizComplete,
    quiz.id,
    result,
    startedAtMs,
  ]);

  const createChallenge = useCallback(async () => {
    if (!result || result.quizType !== "chapter_quiz") {
      return null;
    }

    const response = await fetch(`${backendUrl}/api/quiz/challenges`, {
      method: "POST",
      credentials: "include",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        quizId: result.quizId,
        attemptId: result.attemptId,
      }),
    });

    if (!response.ok) {
      const payload = (await response.json().catch(() => null)) as { error?: string } | null;
      throw new Error(payload?.error ?? "Unable to create challenge link.");
    }

    const json = (await response.json()) as unknown;
    const parsed = quizChallengeResponseSchema.safeParse(json);
    if (!parsed.success) {
      throw new Error("Challenge response could not be parsed.");
    }

    const url = new URL(window.location.href);
    url.searchParams.set("tab", "quiz");
    url.searchParams.set("challengeId", parsed.data.data.challengeId);
    await navigator.clipboard.writeText(url.toString());
    return url.toString();
  }, [backendUrl, result]);

  const startRetake = () => {
    setResult(null);
    setSubmitError(null);
    setAnswers({});
    setCurrentIndex(0);
    setRemainingSeconds(quiz.durationMinutes * 60);
    setStartedAtMs(Date.now());
    setIsSubmitting(false);
    setAnnouncementText("");
    setSlideDirection("left");
  };

  useEffect(() => {
    if (result || isSubmitting || remainingSeconds <= 0) {
      return;
    }

    const intervalId = window.setInterval(() => {
      setRemainingSeconds((previous) => Math.max(0, previous - 1));
    }, TIMER_INTERVAL_MS);

    return () => window.clearInterval(intervalId);
  }, [result, isSubmitting, remainingSeconds]);

  useEffect(() => {
    if (!challengeId) {
      setChallengeError(null);
      setChallengeDetails(null);
      return;
    }

    let cancelled = false;

    const loadChallenge = async () => {
      try {
        setChallengeError(null);
        const response = await fetch(`${backendUrl}/api/quiz/challenges/${challengeId}`, {
          credentials: "include",
        });

        if (!response.ok) {
          const payload = (await response.json().catch(() => null)) as { error?: string } | null;
          if (!cancelled) {
            setChallengeError(payload?.error ?? "Unable to load challenge.");
          }
          return;
        }

        const json = (await response.json()) as unknown;
        const parsed = quizChallengeDetailResponseSchema.safeParse(json);
        if (!parsed.success) {
          if (!cancelled) {
            setChallengeError("Unable to parse challenge details.");
          }
          return;
        }

        if (!cancelled) {
          setChallengeDetails(parsed.data.data);
        }
      } catch {
        if (!cancelled) {
          setChallengeError("Unable to load challenge right now.");
        }
      }
    };

    void loadChallenge();

    return () => {
      cancelled = true;
    };
  }, [backendUrl, challengeId]);

  if (quiz.questions.length === 0) {
    return (
      <EmptyState
        title="No quiz questions yet"
        description="Quiz content for this chapter is being prepared. Review summary, exercises, and flashcards meanwhile."
      />
    );
  }

  /* ─── Result view ─── */
  if (result) {
    return (
      <motion.div
        initial={reduced ? false : { opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={reduced ? { duration: 0 } : { duration: 0.4 }}
        className="space-y-5"
      >
        <QuizResultSummary
          result={result}
          onRetake={startRetake}
          subjectName={subjectName}
          chapterNumber={chapterNumber}
          chapterTitle={chapterTitle}
          onCreateChallenge={quiz.type === "chapter_quiz" ? createChallenge : undefined}
        />
        {isMockExam && result.sectionScores && result.sectionScores.length > 0 && (
          <MockExamResultDetails
            sectionScores={result.sectionScores}
            weakAreas={result.weakAreas}
          />
        )}
        <QuizQuestionReviewList result={result} />
      </motion.div>
    );
  }

  /* ─── Quiz taking view ─── */
  const showNavigator = isMockExam && totalQuestions > QUIZ_NAVIGATOR_THRESHOLD;

  const quizContent = (
    <div className="space-y-5">
      {/* Top bar: counter + timer + progress */}
      <Card className="p-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div>
              <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
                {isMockExam ? "Mock Exam" : "Chapter Quiz"}
              </p>
              <p className="font-display text-lg font-bold text-text-primary">
                Q {currentIndex + 1}
                <span className="text-text-secondary font-normal">/{totalQuestions}</span>
              </p>
            </div>
            <div className="flex flex-wrap gap-1.5">
              <Badge variant="default" size="sm">
                {totalQuestions} questions
              </Badge>
              <Badge variant="default" size="sm">
                {quiz.totalMarks} marks
              </Badge>
              <Badge variant="primary" size="sm">
                {answeredCount} answered
              </Badge>
            </div>
          </div>
          <QuizTimer remainingSeconds={remainingSeconds} expired={isTimeUp && !result} />
        </div>

        {/* Linear progress */}
        <div className="mt-3">
          <LinearProgress
            value={progressPercent}
            barSize="sm"
            colorVariant={isTimeUp ? "danger" : "primary"}
          />
        </div>
      </Card>

      {/* Alerts */}
      {isTimeUp && (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-2 rounded-xl border border-accent-warning/30 bg-accent-warning-light px-4 py-3 text-sm text-accent-warning"
        >
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>Time is up. Answer selection is locked — submit your attempt to view results.</span>
        </motion.div>
      )}

      {submitError && (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-2 rounded-xl border border-accent-danger/30 bg-accent-danger-light px-4 py-3 text-sm text-accent-danger"
        >
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>{submitError}</span>
        </motion.div>
      )}

      {isChallengeMode && challengeError ? (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-2 rounded-xl border border-accent-danger/30 bg-accent-danger-light px-4 py-3 text-sm text-accent-danger"
        >
          <AlertTriangle className="h-4 w-4 shrink-0" />
          <span>{challengeError}</span>
        </motion.div>
      ) : null}

      {isChallengeMode && challengeDetails && !result ? (
        <Card className="border border-accent-primary/20 bg-gradient-to-r from-accent-primary/5 via-bg-surface to-accent-warning-light p-4">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <div className="flex items-center gap-2 text-sm font-semibold text-text-primary">
                <Swords className="h-4 w-4 text-accent-primary" />
                Duel challenge from {challengeDetails.challenger.name}
              </div>
              <p className="mt-1 text-sm text-text-secondary">
                Match the same 10 questions and compare your score side-by-side.
              </p>
            </div>
            <div className="flex flex-wrap gap-2">
              <Badge variant="primary" size="sm">
                {challengeDetails.challenger.score}/{challengeDetails.challenger.totalMarks}
              </Badge>
              <Badge
                variant={challengeDetails.status === "expired" ? "warning" : "default"}
                size="sm"
              >
                <TimerReset className="mr-1 inline h-3.5 w-3.5" />
                Expires {new Date(challengeDetails.expiresAt).toLocaleString()}
              </Badge>
            </div>
          </div>
        </Card>
      ) : null}

      {/* Accessibility announcement */}
      <div aria-live="polite" aria-atomic="true" className="sr-only">
        {announcementText}
      </div>

      {/* Question card with slide transition */}
      <div className="relative overflow-hidden">
        <AnimatePresence mode="wait" custom={slideDirection}>
          <motion.div
            key={currentIndex}
            custom={slideDirection}
            variants={reduced ? undefined : slideVariants}
            initial={reduced ? false : "enter"}
            animate={reduced ? undefined : "center"}
            exit={reduced ? undefined : "exit"}
            transition={reduced ? { duration: 0 } : { duration: 0.25, ease: "easeInOut" }}
          >
            <QuizQuestionCard
              question={currentQuestion}
              questionNumber={currentIndex + 1}
              selectedAnswer={answers[String(currentQuestion.id)]}
              locked={isTimeUp}
              onSelect={(option) => selectAnswer(currentQuestion.id, option)}
            />
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Navigation bar */}
      <Card className="p-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={goPrevious}
              disabled={currentIndex === 0}
              iconLeft={<ChevronLeft />}
            >
              Previous
            </Button>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={skipQuestion}
              disabled={currentIndex === totalQuestions - 1 || isTimeUp}
              iconLeft={<SkipForward />}
            >
              Skip
            </Button>
          </div>

          <div className="flex items-center gap-2">
            {currentIndex < totalQuestions - 1 && (
              <Button
                type="button"
                variant="secondary"
                size="sm"
                onClick={goNext}
                iconRight={<ChevronRight />}
              >
                Next
              </Button>
            )}
            <Button
              type="button"
              variant="primary"
              onClick={submitQuiz}
              disabled={isSubmitting}
              loading={isSubmitting}
              iconLeft={!isSubmitting ? <Send /> : undefined}
            >
              {isTimeUp ? "Submit Time-Up Attempt" : "Submit Quiz"}
            </Button>
          </div>
        </div>

        <p className="mt-2 text-xs text-text-secondary">
          {isMockExam
            ? "Mock exam rule: feedback is shown only after final submission."
            : isChallengeMode
              ? "Submit to lock your duel score and compare it with your friend."
              : "Submit when ready to view your score and explanations."}
        </p>
      </Card>
    </div>
  );

  /* ─── Layout: with navigator sidebar or standalone ─── */
  if (showNavigator) {
    return (
      <div className="flex gap-5">
        <div className="min-w-0 flex-1">{quizContent}</div>
        <div className="hidden w-52 shrink-0 lg:block">
          <div className="sticky top-4">
            <QuestionNavigator
              questions={quiz.questions}
              currentIndex={currentIndex}
              answers={answers}
              onSelectQuestion={goToQuestion}
              isLocked={isTimeUp}
            />
          </div>
        </div>
      </div>
    );
  }

  return quizContent;
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import { Download, Share2, CheckCircle2, XCircle, Trophy } from "lucide-react";

import { Button } from "@/components/ui/button";
import type { QuizResult } from "./quiz-runner";

type ShareableResultCardProps = {
  result: QuizResult;
  subjectName: string;
  chapterNumber?: number;
  chapterTitle?: string;
};

export function ShareableResultCard({
  result,
  subjectName,
  chapterNumber,
  chapterTitle,
}: ShareableResultCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const isDownloadingRef = useRef(false);
  const isSharingRef = useRef(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);

  const appUrl = useMemo(() => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000", []);

  const isMockExam = result.quizType === "mock_exam";
  const passed = result.percentage >= 70;
  const formattedDate = new Date(result.completedAt).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });

  const displayTitle =
    chapterTitle ||
    result.sectionScores?.[0]?.chapterTitle ||
    (isMockExam ? "Mock Exam" : "Chapter Quiz");
  const displayChapterNumber = chapterNumber || result.sectionScores?.[0]?.chapterNumber;

  const correctCount = result.questionResults.filter((q) => q.isCorrect).length;
  const totalCount = result.questionResults.length;

  const handleDownload = useCallback(() => {
    if (isDownloadingRef.current) return;

    isDownloadingRef.current = true;
    setIsDownloading(true);
    try {
      const scale = 2;
      const cardWidth = 400;
      const headerHeight = 88;
      const scoreHeight = 160;
      const footerHeight = 44;
      const cardHeight = headerHeight + scoreHeight + footerHeight;

      const canvas = document.createElement("canvas");
      canvas.width = cardWidth * scale;
      canvas.height = cardHeight * scale;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      ctx.scale(scale, scale);

      // ---------- Header gradient ----------
      const headerGrad = ctx.createLinearGradient(0, 0, cardWidth, headerHeight);
      if (passed) {
        headerGrad.addColorStop(0, "#6366F1");
        headerGrad.addColorStop(0.5, "#8B5CF6");
        headerGrad.addColorStop(1, "#A78BFA");
      } else {
        headerGrad.addColorStop(0, "#F59E0B");
        headerGrad.addColorStop(1, "#EF4444");
      }

      // Rounded top corners
      const radius = 16;
      ctx.beginPath();
      ctx.moveTo(radius, 0);
      ctx.lineTo(cardWidth - radius, 0);
      ctx.quadraticCurveTo(cardWidth, 0, cardWidth, radius);
      ctx.lineTo(cardWidth, headerHeight);
      ctx.lineTo(0, headerHeight);
      ctx.lineTo(0, radius);
      ctx.quadraticCurveTo(0, 0, radius, 0);
      ctx.closePath();
      ctx.fillStyle = headerGrad;
      ctx.fill();

      // Header icon circle
      const iconCx = cardWidth - 24 - 24;
      const iconCy = headerHeight / 2;
      ctx.beginPath();
      ctx.arc(iconCx, iconCy, 24, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(255,255,255,0.2)";
      ctx.fill();

      // Icon text (trophy or X)
      ctx.fillStyle = passed ? "#FFFFFF" : "rgba(255,255,255,0.8)";
      ctx.font = "bold 20px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(passed ? "★" : "✕", iconCx, iconCy);

      // Header text
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      const headerLabelText = isMockExam ? "MOCK EXAM" : "CHAPTER QUIZ";
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.font = "600 10px sans-serif";
      ctx.letterSpacing = "2px";
      ctx.fillText(headerLabelText, 24, 20);

      ctx.fillStyle = "#FFFFFF";
      ctx.font = "bold 17px sans-serif";
      ctx.letterSpacing = "0px";
      ctx.fillText(displayTitle, 24, 36);

      if (displayChapterNumber) {
        ctx.fillStyle = "rgba(255,255,255,0.6)";
        ctx.font = "14px sans-serif";
        ctx.fillText(`Chapter ${displayChapterNumber}`, 24, 60);
      }

      // ---------- Score section (white bg) ----------
      const scoreY = headerHeight;
      ctx.fillStyle = "#FFFFFF";
      ctx.fillRect(0, scoreY, cardWidth, scoreHeight);

      // "YOUR SCORE" label
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "600 10px sans-serif";
      ctx.letterSpacing = "1px";
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("YOUR SCORE", 24, scoreY + 16);

      // Percentage
      ctx.fillStyle = "#111827";
      ctx.font = "bold 36px sans-serif";
      ctx.letterSpacing = "0px";
      ctx.fillText(`${result.percentage}%`, 24, scoreY + 32);

      // Score marks
      ctx.fillStyle = "#6B7280";
      ctx.font = "14px sans-serif";
      ctx.fillText(`${result.score} out of ${result.totalMarks} marks`, 24, scoreY + 74);

      // Questions correct
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "12px sans-serif";
      ctx.fillText(`${correctCount}/${totalCount} questions correct`, 24, scoreY + 94);

      // Right side — "SUBJECT" label
      ctx.textAlign = "right";
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "600 10px sans-serif";
      ctx.letterSpacing = "1px";
      ctx.fillText("SUBJECT", cardWidth - 24, scoreY + 16);

      // Subject name
      ctx.fillStyle = "#111827";
      ctx.font = "bold 17px sans-serif";
      ctx.letterSpacing = "0px";
      ctx.fillText(subjectName, cardWidth - 24, scoreY + 34);

      // Date
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "12px sans-serif";
      ctx.fillText(formattedDate, cardWidth - 24, scoreY + 58);

      // Status badge (centered)
      const badgeText = passed ? "✓  Passed" : "✕  Needs Review";
      ctx.textAlign = "center";
      ctx.font = "600 13px sans-serif";

      const badgeTextWidth = ctx.measureText(badgeText).width;
      const badgePadH = 16;
      const badgePadV = 6;
      const badgeW = badgeTextWidth + badgePadH * 2;
      const badgeH = 28;
      const badgeX = (cardWidth - badgeW) / 2;
      const badgeY = scoreY + scoreHeight - badgeH - 14;

      // Badge background
      const badgeRadius = badgeH / 2;
      ctx.beginPath();
      ctx.moveTo(badgeX + badgeRadius, badgeY);
      ctx.lineTo(badgeX + badgeW - badgeRadius, badgeY);
      ctx.quadraticCurveTo(badgeX + badgeW, badgeY, badgeX + badgeW, badgeY + badgeRadius);
      ctx.quadraticCurveTo(
        badgeX + badgeW,
        badgeY + badgeH,
        badgeX + badgeW - badgeRadius,
        badgeY + badgeH
      );
      ctx.lineTo(badgeX + badgeRadius, badgeY + badgeH);
      ctx.quadraticCurveTo(badgeX, badgeY + badgeH, badgeX, badgeY + badgeRadius);
      ctx.quadraticCurveTo(badgeX, badgeY, badgeX + badgeRadius, badgeY);
      ctx.closePath();
      ctx.fillStyle = passed ? "#ECFDF5" : "#FFFBEB";
      ctx.fill();

      // Badge text
      ctx.fillStyle = passed ? "#047857" : "#B45309";
      ctx.textBaseline = "middle";
      ctx.fillText(badgeText, cardWidth / 2, badgeY + badgeH / 2);

      // ---------- Footer ----------
      const footerY = scoreY + scoreHeight;

      // Rounded bottom corners
      ctx.beginPath();
      ctx.moveTo(0, footerY);
      ctx.lineTo(cardWidth, footerY);
      ctx.lineTo(cardWidth, footerY + footerHeight - radius);
      ctx.quadraticCurveTo(
        cardWidth,
        footerY + footerHeight,
        cardWidth - radius,
        footerY + footerHeight
      );
      ctx.lineTo(radius, footerY + footerHeight);
      ctx.quadraticCurveTo(0, footerY + footerHeight, 0, footerY + footerHeight - radius);
      ctx.closePath();
      ctx.fillStyle = "#F9FAFB";
      ctx.fill();

      // Separator line at top of footer
      ctx.beginPath();
      ctx.moveTo(0, footerY);
      ctx.lineTo(cardWidth, footerY);
      ctx.strokeStyle = "#F3F4F6";
      ctx.lineWidth = 1;
      ctx.stroke();

      // Footer branding
      ctx.textBaseline = "middle";
      ctx.textAlign = "left";
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "bold 12px sans-serif";
      ctx.fillText("Learningo", 24, footerY + footerHeight / 2);

      ctx.textAlign = "right";
      ctx.fillStyle = "#9CA3AF";
      ctx.font = "11px sans-serif";
      ctx.fillText("learningo.pk", cardWidth - 24, footerY + footerHeight / 2);

      // ---------- Export & download ----------
      const dataUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `learningo-result-${result.attemptId}.png`;
      link.href = dataUrl;
      link.click();
    } catch (error) {
      console.error("Failed to download result card:", error);
    } finally {
      isDownloadingRef.current = false;
      setIsDownloading(false);
    }
  }, [
    result.attemptId,
    result.percentage,
    result.score,
    result.totalMarks,
    passed,
    isMockExam,
    displayTitle,
    displayChapterNumber,
    subjectName,
    formattedDate,
    correctCount,
    totalCount,
  ]);

  const handleWhatsAppShare = useCallback(() => {
    if (isSharingRef.current) return;

    isSharingRef.current = true;
    setIsSharing(true);
    try {
      const scoreText = `I scored ${result.score}/${result.totalMarks} (${result.percentage}%) in ${subjectName} ${displayTitle} on Learningo!`;
      const shareUrl = `${appUrl}/learn`;
      const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(`${scoreText}\n\n${shareUrl}`)}`;
      window.open(whatsappUrl, "_blank");
    } catch (error) {
      console.error("Failed to share to WhatsApp:", error);
    } finally {
      isSharingRef.current = false;
      setIsSharing(false);
    }
  }, [result.score, result.totalMarks, result.percentage, subjectName, displayTitle, appUrl]);

  return (
    <div className="space-y-4">
      {/* Shareable card */}
      <div
        ref={cardRef}
        className="overflow-hidden rounded-2xl bg-white shadow-lg"
        style={{ width: "400px" }}
      >
        {/* Header with gradient */}
        <div
          className="px-6 py-5"
          style={{
            background: passed
              ? "linear-gradient(135deg, #6366F1 0%, #8B5CF6 50%, #A78BFA 100%)"
              : "linear-gradient(135deg, #F59E0B 0%, #EF4444 100%)",
          }}
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[11px] font-semibold uppercase tracking-widest text-white/70">
                {isMockExam ? "Mock Exam" : "Chapter Quiz"}
              </p>
              <h3 className="mt-1 text-lg font-bold text-white">{displayTitle}</h3>
              {displayChapterNumber && (
                <p className="text-sm text-white/60">Chapter {displayChapterNumber}</p>
              )}
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white/20 backdrop-blur-sm">
              {passed ? (
                <Trophy className="h-6 w-6 text-white" />
              ) : (
                <XCircle className="h-6 w-6 text-white/80" />
              )}
            </div>
          </div>
        </div>

        {/* Score section */}
        <div className="bg-white px-6 py-5">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold uppercase tracking-wide text-gray-400">
                Your Score
              </p>
              <p className="mt-1 text-4xl font-bold text-gray-900">{result.percentage}%</p>
              <p className="mt-1 text-sm text-gray-500">
                {result.score} out of {result.totalMarks} marks
              </p>
              <p className="mt-0.5 text-xs text-gray-400">
                {correctCount}/{totalCount} questions correct
              </p>
            </div>
            <div className="text-right">
              <p className="text-xs font-semibold uppercase tracking-wide text-gray-400">Subject</p>
              <p className="mt-1 text-lg font-bold text-gray-900">{subjectName}</p>
              <p className="mt-1 text-xs text-gray-400">{formattedDate}</p>
            </div>
          </div>

          {/* Status badge */}
          <div className="mt-4 flex items-center justify-center">
            <span
              className={`inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 text-sm font-semibold ${
                passed ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700"
              }`}
            >
              {passed ? (
                <CheckCircle2 className="h-3.5 w-3.5" />
              ) : (
                <XCircle className="h-3.5 w-3.5" />
              )}
              {passed ? "Passed" : "Needs Review"}
            </span>
          </div>
        </div>

        {/* Footer with branding */}
        <div className="border-t border-gray-100 bg-gray-50 px-6 py-3">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold tracking-wide text-gray-400">Learningo</p>
            <p className="text-[11px] text-gray-400">learningo.pk</p>
          </div>
        </div>
      </div>

      {/* Action buttons */}
      <div className="flex gap-3">
        <Button
          type="button"
          variant="secondary"
          onClick={handleDownload}
          disabled={isDownloading}
          loading={isDownloading}
          iconLeft={!isDownloading ? <Download /> : undefined}
          className="flex-1"
        >
          {isDownloading ? "Generating..." : "Download PNG"}
        </Button>
        <Button
          type="button"
          variant="success"
          onClick={handleWhatsAppShare}
          disabled={isSharing}
          loading={isSharing}
          iconLeft={!isSharing ? <Share2 /> : undefined}
          className="flex-1"
        >
          {isSharing ? "Sharing..." : "Share on WhatsApp"}
        </Button>
      </div>
    </div>
  );
}

