      primary: "text-accent-primary",
      success: "text-accent-success",
      warning: "text-accent-warning",
      danger: "text-accent-danger",
    },
  },
  defaultVariants: {
    colorVariant: "primary",
  },
});

const fillColorMap: Record<string, string> = {
  primary: "bg-accent-primary",
  success: "bg-accent-success",
  warning: "bg-accent-warning",
  danger: "bg-accent-danger",
};

const strokeColorMap: Record<string, string> = {
  primary: "var(--accent-primary)",
  success: "var(--accent-success)",
  warning: "var(--accent-warning)",
  danger: "var(--accent-danger)",
};

/* ═══════════════════════════════════════════
   Linear Progress
   ═══════════════════════════════════════════ */

/** Props for the LinearProgress component. */
export interface LinearProgressProps
  extends
    Omit<HTMLAttributes<HTMLDivElement>, "children">,
    VariantProps<typeof progressColorVariants> {
  /** Current value (0–100). */
  value: number;
  /** Maximum value. Defaults to 100. */
  max?: number;
  /** Show a striped pattern on the fill bar. */
  striped?: boolean;
  /** Optional label shown above the bar. */
  label?: string;
  /** Show the percentage text. */
  showValue?: boolean;
  /** Height of the bar. Defaults to "md". */
  barSize?: "sm" | "md" | "lg";
}

/**
 * Animated linear progress bar with optional stripes and label.
 *
 * Fills from 0 to the target value on mount using Framer Motion.
 */
export function LinearProgress({
  className,
  colorVariant = "primary",
  value,
  max = 100,
  striped = false,
  label,
  showValue = false,
  barSize = "md",
  ...props
}: LinearProgressProps) {
  const percent = Math.min(100, Math.max(0, (value / max) * 100));
  const fill = fillColorMap[colorVariant ?? "primary"] ?? fillColorMap.primary;

  const heightClass = barSize === "sm" ? "h-1.5" : barSize === "lg" ? "h-4" : "h-2.5";

  return (
    <div className={cn("w-full", className)} {...props}>
      {label || showValue ? (
        <div className="mb-1.5 flex items-center justify-between text-xs">
          {label ? <span className="font-medium text-text-primary">{label}</span> : <span />}
          {showValue ? (
            <span className="tabular-nums text-text-secondary">{Math.round(percent)}%</span>
          ) : null}
        </div>
      ) : null}

      <div
        className={cn("w-full overflow-hidden rounded-full bg-bg-subtle", heightClass)}
        role="progressbar"
        aria-valuenow={value}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-label={label ?? "Progress"}
      >
        <motion.div
          className={cn(
            "h-full rounded-full",
            fill,
            striped && [
              "bg-[length:20px_20px]",
              "bg-[linear-gradient(45deg,rgba(255,255,255,.15)_25%,transparent_25%,transparent_50%,rgba(255,255,255,.15)_50%,rgba(255,255,255,.15)_75%,transparent_75%,transparent)]",
            ]
          )}
          initial={{ width: 0 }}
          animate={{ width: `${percent}%` }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        />
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════
   Circular / Ring Progress (XP Rings)
   ═══════════════════════════════════════════ */

/** Props for the CircularProgress component. */
export interface CircularProgressProps
  extends
    Omit<HTMLAttributes<HTMLDivElement>, "children">,
    VariantProps<typeof progressColorVariants> {
  /** Current value (0–100). */
  value: number;
  /** Maximum value. Defaults to 100. */
  max?: number;
  /** Diameter of the SVG in pixels. */
  diameter?: number;
  /** Stroke width of the ring. */
  strokeWidth?: number;
  /** Show the percentage text in the center. */
  showValue?: boolean;
  /** Custom label rendered in the center instead of percentage. */
  label?: string;
}

/**
 * Animated circular/ring progress indicator, ideal for XP rings.
 *
 * Uses an SVG donut and animates the stroke-dashoffset on mount.
 */
export function CircularProgress({
  className,
  colorVariant = "primary",
  value,
  max = 100,
  diameter = 80,
  strokeWidth = 6,
  showValue = true,
  label,
  ...props
}: CircularProgressProps) {
  const percent = Math.min(100, Math.max(0, (value / max) * 100));
  const radius = (diameter - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeColor = strokeColorMap[colorVariant ?? "primary"] ?? strokeColorMap.primary;

  return (
    <div
      className={cn("relative inline-flex items-center justify-center", className)}
      role="progressbar"
      aria-valuenow={value}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-label={label ?? "Progress"}
      {...props}
    >
      <svg
        width={diameter}
        height={diameter}
        viewBox={`0 0 ${diameter} ${diameter}`}
        className="-rotate-90"
      >
        {/* Background ring */}
        <circle
          cx={diameter / 2}
          cy={diameter / 2}
          r={radius}
          fill="none"
          stroke="var(--bg-subtle)"
          strokeWidth={strokeWidth}
        />
        {/* Foreground ring */}
        <motion.circle
          cx={diameter / 2}
          cy={diameter / 2}
          r={radius}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          initial={{ strokeDashoffset: circumference }}
          animate={{
            strokeDashoffset: circumference - (percent / 100) * circumference,
          }}
          transition={{ duration: 1, ease: "easeOut" }}
        />
      </svg>

      {showValue || label ? (
        <span className="absolute inset-0 flex items-center justify-center">
          <span className="text-sm font-semibold tabular-nums text-text-primary">
            {label ?? `${Math.round(percent)}%`}
          </span>
        </span>
      ) : null}
    </div>
  );
}

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type TextareaHTMLAttributes,
  type ReactNode,
} from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/* ─── CVA Textarea Variants ─── */
const textareaVariants = cva(
  [
    "w-full text-text-primary placeholder:text-text-muted",
    "transition-all duration-150 ease-out",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus:outline-none",
    "font-[var(--font-body)]",
    "resize-none",
  ].join(" "),
  {
    variants: {
      variant: {
        default: [
          "bg-bg-surface border border-border-default rounded-lg",
          "shadow-[var(--shadow-sm)]",
          "focus:border-accent-primary focus:ring-2 focus:ring-accent-primary/20",
        ].join(" "),
        ghost: [
          "bg-transparent border-none rounded-lg",
          "focus:bg-bg-subtle focus:ring-2 focus:ring-accent-primary/20",
        ].join(" "),
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

/** Props for the Textarea component. */
export interface TextareaProps
  extends
    Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, "children">,
    VariantProps<typeof textareaVariants> {
  /** Error message displayed below the textarea. */
  error?: string;
  /** Accessible label rendered above the textarea. */
  label?: string;
  /** Enable auto-resize to content height. */
  autoResize?: boolean;
  /** Show a character count indicator. Requires `maxLength` prop. */
  showCount?: boolean;
  /** Maximum number of visible rows before scrolling (only with autoResize). */
  maxRows?: number;
}

/**
 * Form textarea primitive with auto-resize, character count, and error state.
 *
 * Uses `forwardRef` for integration with form libraries.
 */
export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  {
    className,
    variant,
    error,
    label,
    autoResize = false,
    showCount = false,
    maxRows,
    maxLength,
    id,
    rows = 3,
    onChange,
    value,
    defaultValue,
    ...props
  },
  forwardedRef
) {
  const internalRef = useRef<HTMLTextAreaElement | null>(null);
  const textareaId = id ?? props.name;
  const hasError = Boolean(error);

  /* Merge refs */
  const setRefs = useCallback(
    (el: HTMLTextAreaElement | null) => {
      internalRef.current = el;
      if (typeof forwardedRef === "function") {
        forwardedRef(el);
      } else if (forwardedRef) {
        (forwardedRef as React.MutableRefObject<HTMLTextAreaElement | null>).current = el;
      }
    },
    [forwardedRef]
  );

  /* Auto-resize logic */
  const resizeTextarea = useCallback(() => {
    const el = internalRef.current;
    if (!el || !autoResize) return;

    el.style.height = "auto";
    let newHeight = el.scrollHeight;

    if (maxRows) {
      const lineHeight = parseInt(getComputedStyle(el).lineHeight) || 20;
      const maxHeight = lineHeight * maxRows;
      newHeight = Math.min(newHeight, maxHeight);
    }

    el.style.height = `${newHeight}px`;
  }, [autoResize, maxRows]);

  useEffect(() => {
    resizeTextarea();
  }, [value, defaultValue, resizeTextarea]);

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      onChange?.(e);
      resizeTextarea();
    },
    [onChange, resizeTextarea]
  );

  const currentLength = typeof value === "string" ? value.length : 0;

  const errorClasses = hasError
    ? "!border-accent-danger !ring-2 !ring-accent-danger/20 focus:!border-accent-danger focus:!ring-accent-danger/20"
    : "";

  return (
    <div className="w-full space-y-1.5">
      {label ? (
        <label htmlFor={textareaId} className="block text-sm font-medium text-text-primary">
          {label}
        </label>
      ) : null}

      <textarea
        ref={setRefs}
        id={textareaId}
        rows={rows}
        maxLength={maxLength}
        value={value}
        defaultValue={defaultValue}
        onChange={handleChange}
        aria-invalid={hasError || undefined}
        aria-describedby={hasError && textareaId ? `${textareaId}-error` : undefined}
        className={cn(
          textareaVariants({ variant }),
          "min-h-[80px] px-3.5 py-2.5 text-sm",
          autoResize && "overflow-hidden",
          errorClasses,
          className
        )}
        {...props}
      />

      <div className="flex items-center justify-between">
        {hasError && textareaId ? (
          <p id={`${textareaId}-error`} className="text-xs text-accent-danger" role="alert">
            {error}
          </p>
        ) : (
          <span />
        )}

        {showCount && maxLength ? (
          <span
            className={cn(
              "text-xs tabular-nums",
              currentLength >= maxLength ? "text-accent-danger" : "text-text-muted"
            )}
          >
            {currentLength}/{maxLength}
          </span>
        ) : null}
      </div>
    </div>
  );
});

